import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.Cd7uensT.js";const o="/idc_assest-docs/images/screenshots/backup-management.png",u=JSON.parse('{"title":"备份管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/backup-management.md","filePath":"guide/features/backup-management.md","lastUpdated":1788512472000}'),n={name:"guide/features/backup-management.md"};function l(s,t,i,h,b,g){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="备份管理" tabindex="-1">备份管理 <a class="header-anchor" href="#备份管理" aria-label="Permalink to &quot;备份管理&quot;">​</a></h1><p>备份管理用于数据库的备份与恢复，保障数据安全。</p><p><img src="'+o+'" alt="备份管理概览"></p><h2 id="备份管理-1" tabindex="-1">备份管理 <a class="header-anchor" href="#备份管理-1" aria-label="Permalink to &quot;备份管理&quot;">​</a></h2><h3 id="手动备份" tabindex="-1">手动备份 <a class="header-anchor" href="#手动备份" aria-label="Permalink to &quot;手动备份&quot;">​</a></h3><ol><li>进入「备份管理」→「备份管理」页面</li><li>点击「创建备份」按钮</li><li>填写备份名称和描述（选填）</li><li>系统自动创建数据库备份文件</li><li>备份完成后显示在备份列表中，包含备份时间、文件大小、类型等信息</li></ol><h3 id="备份恢复" tabindex="-1">备份恢复 <a class="header-anchor" href="#备份恢复" aria-label="Permalink to &quot;备份恢复&quot;">​</a></h3><ol><li>在备份列表中选择要恢复的备份文件</li><li>点击「恢复」按钮</li><li>仔细阅读恢复提示（恢复会覆盖当前数据）</li><li>系统显示恢复进度，完成后自动重启服务</li></ol><blockquote><p>恢复前建议先对当前数据进行手动备份。</p></blockquote><h3 id="备份文件管理" tabindex="-1">备份文件管理 <a class="header-anchor" href="#备份文件管理" aria-label="Permalink to &quot;备份文件管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>上传</strong></td><td>上传外部备份文件到服务器，支持跨环境恢复</td></tr><tr><td><strong>下载</strong></td><td>下载备份文件到本地保存</td></tr><tr><td><strong>删除</strong></td><td>删除不需要的备份文件</td></tr><tr><td><strong>验证</strong></td><td>校验备份文件的完整性和可用性（显示表数量和记录数）</td></tr><tr><td><strong>清理</strong></td><td>批量清理旧备份，支持按保留份数和天数设置</td></tr></tbody></table><h2 id="自动备份" tabindex="-1">自动备份 <a class="header-anchor" href="#自动备份" aria-label="Permalink to &quot;自动备份&quot;">​</a></h2><p>配置 Cron 表达式设置备份执行时间，支持保留备份文件数量设置。启用自动备份后，系统按设定时间自动创建备份。</p><h2 id="远端备份" tabindex="-1">远端备份 <a class="header-anchor" href="#远端备份" aria-label="Permalink to &quot;远端备份&quot;">​</a></h2><blockquote><p>v2.5.0 增强：支持多目标远端备份管理（FTP/SFTP/WebDAV 协议目标配置）。</p></blockquote><p>支持将备份文件自动传输到远端存储，协议包括 FTP、SFTP、WebDAV。</p><h3 id="远端目标管理" tabindex="-1">远端目标管理 <a class="header-anchor" href="#远端目标管理" aria-label="Permalink to &quot;远端目标管理&quot;">​</a></h3><blockquote><p>v2.5.0 新增多目标管理，可配置多个远端存储目标。</p></blockquote><p>进入「备份管理」→「远端备份」标签，可管理多个远端备份目标：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加目标</strong></td><td>配置远端存储信息（协议、主机、端口、路径、账号）</td></tr><tr><td><strong>编辑目标</strong></td><td>修改已有远端目标配置</td></tr><tr><td><strong>删除目标</strong></td><td>删除不再使用的远端目标</td></tr><tr><td><strong>测试连接</strong></td><td>验证远端目标配置是否可用</td></tr><tr><td><strong>启用/禁用</strong></td><td>控制该目标是否参与自动备份上传</td></tr></tbody></table><h4 id="支持的协议" tabindex="-1">支持的协议 <a class="header-anchor" href="#支持的协议" aria-label="Permalink to &quot;支持的协议&quot;">​</a></h4><table tabindex="0"><thead><tr><th>协议</th><th>说明</th></tr></thead><tbody><tr><td><strong>FTP</strong></td><td>传统文件传输协议，端口默认 21</td></tr><tr><td><strong>SFTP</strong></td><td>基于 SSH 的安全文件传输，端口默认 22</td></tr><tr><td><strong>WebDAV</strong></td><td>基于 HTTP 的分布式文件系统，支持 HTTPS</td></tr></tbody></table><h4 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h4><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>目标名称</strong></td><td>远端目标显示名称</td></tr><tr><td><strong>协议类型</strong></td><td>FTP / SFTP / WebDAV</td></tr><tr><td><strong>主机地址</strong></td><td>远端服务器地址</td></tr><tr><td><strong>端口</strong></td><td>服务端口（按协议默认）</td></tr><tr><td><strong>根路径</strong></td><td>远端存储根目录路径</td></tr><tr><td><strong>用户名</strong></td><td>登录账号</td></tr><tr><td><strong>密码</strong></td><td>登录密码或密钥</td></tr><tr><td><strong>启用状态</strong></td><td>是否启用该目标</td></tr></tbody></table><h3 id="远端配置" tabindex="-1">远端配置 <a class="header-anchor" href="#远端配置" aria-label="Permalink to &quot;远端配置&quot;">​</a></h3><ol><li>进入「备份管理」→「远端备份」标签</li><li>点击「添加配置」，填写远端存储信息</li><li>点击「测试连接」验证配置</li><li>测试通过后保存配置</li></ol><h3 id="手动同步" tabindex="-1">手动同步 <a class="header-anchor" href="#手动同步" aria-label="Permalink to &quot;手动同步&quot;">​</a></h3><p>选择本地备份文件，手动触发上传到远端存储。</p><h3 id="自动备份上传" tabindex="-1">自动备份上传 <a class="header-anchor" href="#自动备份上传" aria-label="Permalink to &quot;自动备份上传&quot;">​</a></h3><p>在「自动备份设置」中配置远端备份目标后，系统在自动备份完成后，会将备份文件自动上传到所有启用的远端目标。</p><h3 id="远端备份设置" tabindex="-1">远端备份设置 <a class="header-anchor" href="#远端备份设置" aria-label="Permalink to &quot;远端备份设置&quot;">​</a></h3><blockquote><p>v2.5.0 新增全局远端备份设置。</p></blockquote><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>启用远端备份</strong></td><td>全局开关，控制是否执行远端上传</td></tr><tr><td><strong>上传目标</strong></td><td>选择参与自动上传的远端目标</td></tr><tr><td><strong>失败重试</strong></td><td>上传失败时的重试策略</td></tr></tbody></table>',33)])])}const p=a(n,[["render",l]]);export{u as __pageData,p as default};
